def max_window_sum(xs):
    # Brute force: the largest sum over every non-empty run xs[i..j].
    n = len(xs)
    best = xs[0]
    for i in range(n):
        s = 0
        for j in range(i, n):
            s += xs[j]
            if s > best:
                best = s
    return best


def post(xs, result):
